import json
def solve(p):
    rules={}
    for line in open(f'{p}/rules.txt'):
        line=line.strip()
        if '=' in line:
            k,v=line.split('=',1); rules[k]=v
    cand={c['assessment_ref']:c for c in (json.loads(l) for l in open(f'{p}/candidates.jsonl'))}
    asm={a['ref']:a for a in (json.loads(l) for l in open(f'{p}/assessments.jsonl'))}
    res=[]
    for ref,a in asm.items():
        c=cand[ref]
        if (c['state']==rules['required_state'] and c['lane']==rules['required_lane']
            and a['score']>=int(rules['minimum_score']) and a['clearance']==rules['required_clearance']):
            res.append(c['code'])
    return res
a=solve('packet_a'); b=solve('packet_b')
print(a,b)
print(" / ".join([a[0], b[0]]) if len(a)==1 and len(b)==1 else "???")

