import json

def load_jsonl(path):
    rows=[]
    with open(path) as f:
        for line in f:
            line=line.strip()
            if line:
                rows.append(json.loads(line))
    return rows

for pkt in ['packet_a','packet_b']:
    print(f"=== {pkt}/rules.txt ===")
    print(open(f'{pkt}/rules.txt').read())
    print(f"=== {pkt}/candidates.jsonl ===")
    for r in load_jsonl(f'{pkt}/candidates.jsonl'):
        print(r)
    print(f"=== {pkt}/assessments.jsonl ===")
    for r in load_jsonl(f'{pkt}/assessments.jsonl'):
        print(r)

